2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	)
10	
11	// RecordInfo 描述一次保存产生的记录的元信息。
12	type RecordInfo struct {
13		// ID 是记录在存档目录内的唯一标识。
14		ID RecordID
15		// Parent 是父记录标识；直接建立的槽首条记录为空。
16		Parent RecordID
17		// SlotFirst 表示这是所在槽的首条记录（根记录或分支记录）。
18		SlotFirst bool
19		// Version 是记录中世界规则的版本。
20		Version string
21	}
22	
23	// slotPointer 是槽指针文件的磁盘内容，指向该槽当前最新记录。
24	//
25	// History 按该槽“保存生效的次序”记录全部属于本槽的记录标识，最新在前，
26	// 末尾是槽首条记录（直接建立的根记录或分支首记录）。它只在对应记录文件
27	// 已完整落盘后才随指针原子更新，因此绝不会包含写了一半的残留文件、写完
28	// 但尚未完成保存的孤儿记录，或 CAS 竞争失败的写入。恢复读取据此遍历，
29	// 不依赖文件修改时间，也不信任受损记录文件里读出的父标识或槽首标记。
30	//
31	// 旧版本写出的指针没有 History 字段；读取时会在内存中按校验通过的父链
32	// 回退重建，不要求用户转换数据。
33	type slotPointer struct {
34		Latest  RecordID   `json:"latest"`
35		History []RecordID `json:"history,omitempty"`
36	}
37	
38	// archiveMarker 是存档目录的标记文件。
39	type archiveMarker struct {
40		Format int `json:"format"`
41	}
42	
43	// Archive 是一个本地存档目录句柄。多个进程或多个实例可以同时打开
44	// 同一目录；所有写入通过目录内的 flock 串行化。
45	type Archive struct {
46		dir string
47	}
48	
49	const (
50		markerName  = "archive.json"
51		recordsName = "records"
52		slotsName   = "slots"
53	)
54	
55	// Create 在指定目录建立新的存档。目录会被创建；若该目录已经是一个
56	// 存档则返回错误，以免覆盖已有数据。
57	//
58	// 创建有明确的结果：要么完整成功并返回可立即使用的句柄，要么返回
59	// 错误且不返回句柄。准备必要目录、写入存档标记或建立锁文件时出错，
60	// 都会把指明失败操作与位置的错误交给调用方，并撤回本次创建已产生的
61	// 标记、锁文件与子目录——回退只限本次新增的内容：目录里原有的文件与
62	// 子目录（包括原本就存在、可直接使用的空 records/slots 子目录）以及
63	// 调用前已存在的目标目录本身都保持原样。因此失败后排除障碍即可用
64	// 同一路径重新创建，不会被上一次失败留下的标记拒绝。
65	func Create(dir string) (_ *Archive, err error) {
66		// 本次调用新产生的内容，失败时按相反顺序撤回；调用前已存在的
67		// 任何内容都不在撤回范围内。
68		var created []string
69		defer func() {
70			if err != nil {
71				for i := len(created) - 1; i >= 0; i-- {
72					os.Remove(created[i])
73				}
74			}
75		}()
76	
77		// 目标目录在调用前已存在时保留它（包括失败回退时）；不存在才
78		// 由本次创建建立，并纳入回退范围。
79		if _, statErr := os.Stat(dir); statErr != nil {
80			if !errors.Is(statErr, os.ErrNotExist) {
81				return nil, fmt.Errorf("检查存档目录 %s: %w", dir, statErr)
82			}
83			if err := os.MkdirAll(dir, 0o755); err != nil {
84				return nil, fmt.Errorf("建立存档目录 %s: %w", dir, err)
85			}
86			created = append(created, dir)
87		}
88	
89		markerPath := filepath.Join(dir, markerName)
90		f, err := os.OpenFile(markerPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
91		if err != nil {
92			if errors.Is(err, os.ErrExist) {
93				// 已有存档：原样保留既有标记（即使它无法解析），不覆盖，
94				// 也不借回退删除；此时本次尚未产生任何新内容。
95				return nil, &ConflictError{Reason: "目录已是一个存档: " + dir}
96			}
97			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
98		}
99		created = append(created, markerPath)
100		markerData, _ := json.Marshal(archiveMarker{Format: archiveFormatVersion})
101		if _, err := f.Write(markerData); err != nil {
102			f.Close()
103			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
104		}
105		if err := f.Close(); err != nil {
106			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
107		}
108	
109		for _, sub := range []string{recordsName, slotsName} {
110			subPath := filepath.Join(dir, sub)
111			if fi, statErr := os.Stat(subPath); statErr == nil {
112				if !fi.IsDir() {
113					return nil, fmt.Errorf("建立存档子目录 %s: 位置已被同名文件占用", subPath)
114				}
115				// 原本就存在的子目录直接沿用，回退时保留。
116				continue
117			} else if !errors.Is(statErr, os.ErrNotExist) {
118				return nil, fmt.Errorf("检查存档子目录 %s: %w", subPath, statErr)
119			}
120			if err := os.Mkdir(subPath, 0o755); err != nil {
121				return nil, fmt.Errorf("建立存档子目录 %s: %w", subPath, err)
122			}
123			created = append(created, subPath)
124		}
125	
126		// 预先建立锁文件并同步目录，使之后的打开更稳妥。锁位置已被占用
127		// （例如已是一个目录）时明确报错，而不是留到首次保存才失败。
128		lockPath := filepath.Join(dir, "lock")
129		_, lockStatErr := os.Stat(lockPath)
130		lockExisted := lockStatErr == nil
131		if lockStatErr != nil && !errors.Is(lockStatErr, os.ErrNotExist) {
132			return nil, fmt.Errorf("检查存档锁文件 %s: %w", lockPath, lockStatErr)
133		}
134		lf, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o600)
135		if err != nil {
136			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
137		}
138		if err := lf.Close(); err != nil {
139			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
140		}
141		if !lockExisted {
142			created = append(created, lockPath)
143		}
144	
145		if err := syncDir(dir); err != nil {
146			return nil, fmt.Errorf("同步存档目录 %s: %w", dir, err)
147		}
148		return &Archive{dir: dir}, nil
149	}
150	
151	// Open 打开一个此前由 Create 建立的存档目录。
152	func Open(dir string) (*Archive, error) {
153		path := filepath.Join(dir, markerName)
154		f, err := os.Open(path)
155		if err != nil {
156			if errors.Is(err, os.ErrNotExist) {
157				return nil, &NotFoundError{}
158			}
159			return nil, err
160		}
161		defer f.Close()
162		var m archiveMarker
163		if err := json.NewDecoder(f).Decode(&m); err != nil {
164			return nil, &CorruptError{Reason: "存档标记无法解析"}
165		}
166		if m.Format != archiveFormatVersion {
167			return nil, &CorruptError{Reason: "不支持的存档格式版本"}
168		}
169		for _, sub := range []string{recordsName, slotsName} {
170			if fi, err := os.Stat(filepath.Join(dir, sub)); err != nil || !fi.IsDir() {
171				return nil, &CorruptError{Reason: "存档目录结构不完整: 缺少 " + sub}
172			}
173		}
174		return &Archive{dir: dir}, nil
175	}
176	
177	// Dir 返回存档目录路径。
178	func (a *Archive) Dir() string { return a.dir }
179	
180	func (a *Archive) slotPath(slot string) string {
181		return filepath.Join(a.dir, slotsName, slot+".json")
182	}
183	
184	// validSlotName 拒绝空名以及可能逃逸 slots 目录的名字。
185	func validSlotName(slot string) bool {
186		if slot == "" || slot == "." || slot == ".." {
187			return false
188		}
189		if filepath.IsAbs(slot) {
190			return false
191		}
192		for _, r := range slot {
193			if r == '/' || r == '\\' || r == 0 {
194				return false
195			}
196		}
197		return filepath.Clean(slot) == slot
198	}
199	
200	// readSlotPointerLocked 在调用方已持锁的前提下读取并解析槽指针文件。
201	func (a *Archive) readSlotPointerLocked(slot string) (slotPointer, error) {
202		data, err := os.ReadFile(a.slotPath(slot))
203		if err != nil {
204			if errors.Is(err, os.ErrNotExist) {
205				return slotPointer{}, &NotFoundError{Slot: slot}
206			}
207			return slotPointer{}, err
208		}
209		var p slotPointer
210		if err := json.Unmarshal(data, &p); err != nil {
211			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
212		}
213		if p.Latest == "" {
214			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针为空"}
215		}
216		return p, nil
217	}
218	
219	// readLatestLocked 在调用方已持锁的前提下读取槽当前最新记录标识。
220	func (a *Archive) readLatestLocked(slot string) (RecordID, error) {
221		p, err := a.readSlotPointerLocked(slot)
222		if err != nil {
223			return "", err
224		}
225		return p.Latest, nil
226	}
227	
228	// Save 在存档中保存一个世界。
229	//
230	// 首次保存会创建同名存档槽；槽名已存在时返回 *ConflictError。
231	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。
232	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
233		if !validSlotName(slot) {
234			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
235		}
236		st := w.Snapshot()
237	
238		lock, err := acquireLock(a.dir)
239		if err != nil {
240			return RecordInfo{}, err
241		}
242		defer lock.release()
243	
244		// 持锁后再次确认槽不存在。
245		if _, err := a.readLatestLocked(slot); err == nil {
246			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
247		} else if !errors.As(err, new(*NotFoundError)) {
248			return RecordInfo{}, err
249		}
250	
251		id, err := newRecordID()
252		if err != nil {
253			return RecordInfo{}, err
254		}
255		env := &envelope{
256			Format:    recordFormatVersion,
257			ID:        id,
258			SlotFirst: true,
259			State:     st,
260		}
261		env.Checksum = computeChecksum(env)
262		if err := writeRecord(a.dir, env); err != nil {
263			return RecordInfo{}, err
264		}
265		if err := a.createSlotPointer(slot, id); err != nil {
266			return RecordInfo{}, err
267		}
268		return RecordInfo{ID: id, SlotFirst: true, Version: st.Rules.Version}, nil
269	}
270	
271	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
272	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
273	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。新槽的
274	// 历史索引只含其首条记录本身——分支槽不会把来源槽的记录计入候选。
275	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
276		slotsDir := filepath.Join(a.dir, slotsName)
277		final := a.slotPath(slot)
278		data, _ := json.MarshalIndent(slotPointer{
279			Latest:  id,
280			History: []RecordID{id},
281		}, "", "  ")
282	
283		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
284		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
285		if err != nil {
286			return err
287		}
288		if _, err := f.Write(data); err != nil {
289			f.Close()
290			os.Remove(tmp)
291			return err
292		}
293		if err := f.Sync(); err != nil {
294			f.Close()
295			os.Remove(tmp)
296			return err
297		}
298		if err := f.Close(); err != nil {
299			os.Remove(tmp)
300			return err
301		}
302		if err := os.Link(tmp, final); err != nil {
303			os.Remove(tmp)
304			if errors.Is(err, os.ErrExist) {
305				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
306			}
307			return err
308		}
309		os.Remove(tmp)
310		return syncDir(slotsDir)
311	}
312	
313	// Replace 用世界当前状态覆盖槽的最新记录。
314	//
315	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
316	// 写入才会发生；否则返回 *ConflictError——即使该标识对应的旧文件恰好
317	// 已损坏或被删除，过期请求也只报冲突，不改报文件错误。标识匹配时还要
318	// 确认这条当前记录本身可正常读取：文件缺失返回 *NotFoundError；格式版本
319	// 不受支持、截断、校验和不匹配、世界状态不合法或父记录缺失返回
320	// *CorruptError。绝不用
321	// 调用方传入的完整世界掩盖当前记录的问题，也不自动改选较老记录为父。
322	// 新记录的父记录就是被覆盖的那次记录。同一目录下并发覆盖同一父记录时
323	// 只有一个成功。被拒绝的覆盖不改变槽指向、历史与任何已有记录。
324	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
325		if !validSlotName(slot) {
326			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
327		}
328		if expected == "" {
329			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
330		}
331		st := w.Snapshot()
332	
333		lock, err := acquireLock(a.dir)
334		if err != nil {
335			return RecordInfo{}, err
336		}
337		defer lock.release()
338	
339		pointer, err := a.readSlotPointerLocked(slot)
340		if err != nil {
341			return RecordInfo{}, err
342		}
343		if pointer.Latest != expected {
344			return RecordInfo{}, &ConflictError{
345				Slot:   slot,
346				Reason: "所依据的记录已不是该槽最新记录",
347			}
348		}
349	
350		// 标识匹配后，当前记录本身必须可正常读取：格式受支持、完整、内容
351		// 校验通过、世界状态合法且父记录关系成立。否则以它为父保存的新记录随后也
352		// 无法读取，等于用调用方传入的完整世界掩盖了当前记录的问题；
353		// 这里沿用与读取路径一致的校验，损坏或缺失时拒绝覆盖，槽指向、
354		// 历史与已有记录保持原样，调用方可改走恢复预览与确认恢复。
355		if _, err := a.loadAndVerifyLocked(expected); err != nil {
356			if ce, ok := err.(*CorruptError); ok {
357				ce.Slot = slot
358			}
359			return RecordInfo{}, err
360		}
361	
362		// 覆盖保存传入世界的快照，以被覆盖的当前记录为父，沿用共同的
363		// 新记录组装、落盘与槽指针提交路径。
364		return a.appendSlotRecordLocked(slotSave{
365			slot:          slot,
366			oldPointer:    pointer,
367			parent:        expected,
368			historyAnchor: expected,
369			state:         st,
370		})
371	}
372	
373	// commitSlotPointerLocked 在记录文件已完整落盘后，原子更新槽指针：指向
374	// 新记录，并把历史索引按保存次序前置新记录。历史索引只在此刻（记录已
375	// 完整生效）才更新，因此残留临时文件与写完但未完成保存的孤儿记录绝不会
376	// 进入恢复候选。
377	func (a *Archive) commitSlotPointerLocked(slot string, oldPointer slotPointer, oldLatest, newID RecordID) error {
378		history, err := a.nextSlotHistoryLocked(oldPointer, oldLatest, newID)
379		if err != nil {
380			return err
381		}
382		return a.persistSlotPointerLocked(slot, slotPointer{Latest: newID, History: history})
383	}
384	
385	// replaceSlotPointer 直接把槽指针指向 id，不附带历史索引。它仅用于测试
386	// 中模拟旧版本或外部写入器留下的指针；生产写入路径一律走
387	// commitSlotPointerLocked 以维护历史索引。
388	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
389		return a.persistSlotPointerLocked(slot, slotPointer{Latest: id})
390	}
391	
392	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
393	//
394	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
395	// 目标槽名已存在时返回 *ConflictError。源记录必须校验通过。
396	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
397		if !validSlotName(srcSlot) {
398			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
399		}
400		if !validSlotName(dstSlot) {
401			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
402		}
403		if src == "" {
404			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
405		}
406	
407		lock, err := acquireLock(a.dir)
408		if err != nil {
409			return RecordInfo{}, err
410		}
411		defer lock.release()
412	
413		srcEnv, err := a.loadAndVerifyLocked(src)
414		if err != nil {
415			return RecordInfo{}, err
416		}
417		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
418		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
419			return RecordInfo{}, err
420		}
421		// 目标槽重名拒绝创建。
422		if _, err := a.readLatestLocked(dstSlot); err == nil {
423			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
424		} else if !errors.As(err, new(*NotFoundError)) {
425			return RecordInfo{}, err
426		}
427	
428		id, err := newRecordID()
429		if err != nil {
430			return RecordInfo{}, err
431		}
432		env := &envelope{
433			Format:    recordFormatVersion,
434			ID:        id,
435			Parent:    src,
436			SlotFirst: true,
437			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
438			State: cloneState(srcEnv.State),
439		}
440		env.Checksum = computeChecksum(env)
441		if err := writeRecord(a.dir, env); err != nil {
442			return RecordInfo{}, err
443		}
444		if err := a.createSlotPointer(dstSlot, id); err != nil {
445			return RecordInfo{}, err
446		}
447		return RecordInfo{
448			ID:        id,
449			Parent:    src,
450			SlotFirst: true,
451			Version:   env.State.Rules.Version,
452		}, nil
453	}
454	
455	// assertInSlotHistoryLocked 确认 id 位于 slot 自身的历史次序中（分支槽
456	// 的历史只含它自己保存成功的记录，不含来源槽记录）。
457	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
458		history, err := a.slotHistoryLocked(slot)
459		if err != nil {
460			return err
461		}
462		for _, cid := range history {
463			if cid == id {
464				return nil
465			}
466		}
467		return &NotFoundError{Slot: slot, Record: id}
468	}
469	
470	// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
471	// 槽首记录在末尾）。
472	//
473	// 优先使用指针内嵌的历史索引；旧版本指针没有该索引时，在内存中沿
474	// “校验通过”的记录父链回退重建，绝不在读取路径上改写目录。重建在缺失、
475	// 无法解析或校验不过的记录处停止——无法确认归属的更老记录不再使用。
476	// 槽首标记只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首
477	// 标记既不能把遍历引向别的槽，也不能遮住本槽更早的可用记录。
478	func (a *Archive) slotHistoryLocked(slot string) ([]RecordID, error) {
479		p, err := a.readSlotPointerLocked(slot)
480		if err != nil {
481			return nil, err
482		}
483		if len(p.History) > 0 {
484			// 以 Latest 为链头做一次去重规范化，容忍索引中的重复项。
485			return dedupeRecordIDs(append([]RecordID{p.Latest}, p.History...)), nil
486		}
487		return a.rebuildHistoryLocked(p.Latest)
488	}
489	
490	// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史，
491	// 只返回仍能确认属于本槽的记录；在缺失、无法解析或校验不过的记录处停止。
492	func (a *Archive) rebuildHistoryLocked(latest RecordID) ([]RecordID, error) {
493		var chain []RecordID
494		seen := map[RecordID]bool{}
495		cur := latest
496		for cur != "" {
497			if seen[cur] {
498				return nil, &CorruptError{Record: cur, Reason: "历史链出现环"}
499			}
500			seen[cur] = true
501			env, err := a.loadAndVerifyLocked(cur)
502			if err != nil {
503				// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
504				// 旧历史在此断裂；已确认的部分仍可使用。
505				return chain, nil
506			}
507			chain = append(chain, cur)
508			if env.SlotFirst {
509				return chain, nil
510			}
511			cur = env.Parent
512		}
513		return chain, nil
514	}
515	
516	// dedupeRecordIDs 按首次出现次序去重记录标识。
517	func dedupeRecordIDs(ids []RecordID) []RecordID {
518		seen := map[RecordID]bool{}
519		out := ids[:0]
520		for _, id := range ids {
521			if id == "" || seen[id] {
522				continue
523			}
524			seen[id] = true
525			out = append(out, id)
526		}
527		return out
528	}
529	
530	// persistSlotPointerLocked 以原子改名写出槽指针。
531	func (a *Archive) persistSlotPointerLocked(slot string, p slotPointer) error {
532		data, _ := json.MarshalIndent(p, "", "  ")
533		return writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data)
534	}
535	
536	// nextSlotHistory 在一次以 oldLatest 为被覆盖/升级记录的成功写入后，
537	// 生成新指针应持有的历史次序：新记录在最前，其余沿用此前已确认属于
538	// 本槽的记录。旧指针无索引时在内存中回退重建（不完整也照样承接），
539	// 从而让旧历史在第一次成功覆盖或升级后获得完整恢复能力。
540	func (a *Archive) nextSlotHistoryLocked(oldPointer slotPointer, oldLatest, newID RecordID) ([]RecordID, error) {
541		base := oldPointer.History
542		if len(base) == 0 {
543			rebuilt, err := a.rebuildHistoryLocked(oldLatest)
544			if err != nil {
545				return nil, err
546			}
547			base = rebuilt
548		}
549		return dedupeRecordIDs(append([]RecordID{newID}, base...)), nil
550	}
551	
552	// Slots 返回所有存档槽名。
553	func (a *Archive) Slots() ([]string, error) {
554		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
555		if err != nil {
556			return nil, err
557		}
558		var names []string
559		for _, e := range entries {
560			if e.IsDir() {
561				continue
562			}
563			name := e.Name()
564			if len(name) > 5 && name[len(name)-5:] == ".json" {
565				names = append(names, name[:len(name)-5])
566			}
567		}
568		return names, nil
569	}
