134		}
135		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
136			return Record{}, &VersionRejectedError{
137				Slot:     slot,
138				Record:   id,
139				Version:  env.State.Rules.Version,
140				Accepted: append([]string(nil), acceptedVersions...),
141			}
142		}
143		return envToRecord(env), nil
144	}
