146	// Record 按标识读取槽的一份历史记录（覆盖后的旧记录仍可读取）。
147	//
148	// 与 Latest 一样检查记录格式版本、内容校验和（含父记录关系）与规则版本，
149	// 且记录必须属于该槽的历史链。读取不会改写存档，也不会改变规则版本。
150	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
151		if !validSlotName(slot) {
152			return Record{}, &NotFoundError{Slot: slot}
153		}
154		lock, err := acquireSharedLock(a.dir)
155		if err != nil {
156			return Record{}, err
157		}
158		defer lock.release()
159	
160		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
161			return Record{}, err
162		}
