1	package world
2	
3	import "sort"
4	
5	// maxGenerateLocations 是生成地图允许的最大地点数量。
6	const maxGenerateLocations = 256
7	
8	// GenerateRequest 是按种子生成地图并建立世界的请求。
9	//
10	// Seed 是整数地图种子，支持完整的 int64 范围（含零和负数）。Locations
11	// 是地图地点；Required 是必有道路，Banned 是禁用道路，RoadCount 是
12	// 生成后不同道路的总数。道路无向：同一道路重复出现或反向列出只算一条。
13	// RulesVersion、ItemKinds、CarryLimits 与 Characters 与 NewWorld 的
14	// 对应输入含义相同，它们不参与地图生成，改变它们不影响生成的地图。
15	type GenerateRequest struct {
16		// Seed 是整数地图种子。
17		Seed int64
18		// Locations 是地图地点，1 至 256 个，标识非空且不重复。
19		Locations []string
20		// Required 是必须包含的道路，可以成环。
21		Required []Edge
22		// Banned 是必须避开的道路。
23		Banned []Edge
24		// RoadCount 是生成后不同道路的总数。
25		RoadCount int
26		// RulesVersion 是规则版本。
27		RulesVersion string
28		// ItemKinds 是允许出现的物品种类。
29		ItemKinds []string
30		// CarryLimits 给出每个角色可携带物品的总量上限。
31		CarryLimits map[string]int
32		// Characters 是初始角色集合。
33		Characters []Character
34	}
35	
36	// GenerateWorld 按种子生成地图并建立世界。生成的地图是无向道路图：
37	// 包含全部必有道路、避开全部禁用道路、任意两个地点之间都能沿道路到达，
38	// 且不同道路的数量严格等于请求的目标数量；同一道路只保留一条，输出中
39	// 道路方向与排列是规范的（端点按字典序、道路按端点排序）。
40	//
41	// 同一种子和同一组地图约束生成的地点与道路内容、方向表示和排列完全
42	// 一致，与调用先后、是否生成过其他世界及进程是否重启无关；地点与两类
43	// 道路的输入次序、重复道路或正反写法不影响结果。存在多种合法地图时，
44	// 不同种子可以产生不同道路组合。约束不合法（地点数量越界、标识为空或
45	// 重复、道路引用未知地点或连接自身、同一道路同时必有和禁用、目标数量
46	// 为负、小于必有道路数、少于连通全图所需数量、超过可用道路数，或禁用
47	// 道路使地图无法连通）时返回 *RuleError，不会产生可用世界；约束有解时
48	// 每个种子都能成功生成。
49	//
50	// 生成不修改调用方输入；规则版本、角色、物品种类与携带上限按输入保留，
51	// 时间片从零开始。除此之外与 NewWorld 行为一致。
52	func GenerateWorld(req GenerateRequest) (*World, error) {
53		locs, edges, err := generateMap(req.Seed, req.Locations, req.Required, req.Banned, req.RoadCount)
54		if err != nil {
55			return nil, err
56		}
57		return NewWorld(InitialData{
58			Seed: req.Seed,
59			Rules: Rules{
60				Version:     req.RulesVersion,
61				Locations:   locs,
62				Edges:       edges,
63				ItemKinds:   req.ItemKinds,
64				CarryLimits: req.CarryLimits,
65			},
66			Characters: req.Characters,
67		})
68	}
69	
70	// canonicalEdge 把一条无向道路规范为端点字典序较小的在前。
71	func canonicalEdge(e Edge) Edge {
72		if e.To < e.From {
73			return Edge{From: e.To, To: e.From}
74		}
75		return e
76	}
77	
78	// generateMap 按种子与地图约束生成规范的地点列表和道路列表。
79	// 输入切片不会被修改。
80	func generateMap(seed int64, locations []string, required, banned []Edge, roadCount int) ([]string, []Edge, error) {
81		n := len(locations)
82		if n < 1 || n > maxGenerateLocations {
83			return nil, nil, ruleErrorf("地点数量必须在 1 到 %d 之间: %d", maxGenerateLocations, n)
84		}
85		locs := append([]string(nil), locations...)
86		sort.Strings(locs)
87		locSet := make(map[string]struct{}, n)
88		for _, l := range locs {
89			if l == "" {
90				return nil, nil, ruleErrorf("地点标识不能为空")
91			}
92			if _, ok := locSet[l]; ok {
93				return nil, nil, ruleErrorf("地点标识重复: %q", l)
94			}
95			locSet[l] = struct{}{}
96		}
97	
98		// 必有与禁用道路各自去重（反向列出算同一条），并校验端点。
99		reqSet := make(map[Edge]struct{}, len(required))
100		for _, e := range required {
101			if err := checkMapEdge(e, locSet, "必有道路"); err != nil {
102				return nil, nil, err
103			}
104			reqSet[canonicalEdge(e)] = struct{}{}
105		}
106		banSet := make(map[Edge]struct{}, len(banned))
107		for _, e := range banned {
108			if err := checkMapEdge(e, locSet, "禁用道路"); err != nil {
109				return nil, nil, err
110			}
111			banSet[canonicalEdge(e)] = struct{}{}
112		}
113		for e := range reqSet {
114			if _, ok := banSet[e]; ok {
115				return nil, nil, ruleErrorf("道路 %q-%q 不能同时必有和禁用", e.From, e.To)
116			}
117		}
118	
119		if roadCount < 0 {
120			return nil, nil, ruleErrorf("目标道路数量不能为负: %d", roadCount)
121		}
122		if roadCount < len(reqSet) {
123			return nil, nil, ruleErrorf("目标道路数量 %d 小于必有道路数量 %d", roadCount, len(reqSet))
124		}
125	
126		// 候选道路：全部地点两两组合中未被禁用的道路，按规范次序排列。
127		candidates := make([]Edge, 0, n*(n-1)/2)
128		for i := 0; i < n; i++ {
129			for j := i + 1; j < n; j++ {
130				e := Edge{From: locs[i], To: locs[j]}
131				if _, ok := banSet[e]; !ok {
132					candidates = append(candidates, e)
133				}
134			}
135		}
136		if roadCount > len(candidates) {
137			return nil, nil, ruleErrorf("目标道路数量 %d 超过可用道路数量 %d", roadCount, len(candidates))
138		}
139	
140		index := make(map[string]int, n)
141		for i, l := range locs {
142			index[l] = i
143		}
144	
145		// 必有道路先并入并查集；连通全图最少还需要 (分量数-1) 条道路。
146		uf := newUnionFind(n)
147		components := n
148		for e := range reqSet {
149			if uf.union(index[e.From], index[e.To]) {
150				components--
151			}
152		}
153		if minNeeded := len(reqSet) + components - 1; roadCount < minNeeded {
154			return nil, nil, ruleErrorf("目标道路数量 %d 少于连通全图所需数量 %d", roadCount, minNeeded)
155		}
156	
157		// 禁用道路不得使地图无法连通：全部候选道路必须能连成一片。
158		{
159			full := newUnionFind(n)
160			c := n
161			for _, e := range candidates {
162				if full.union(index[e.From], index[e.To]) {
163					c--
164				}
165			}
166			if c > 1 {
167				return nil, nil, ruleErrorf("禁用道路使地图无法连通")
168			}
169		}
170	
171		// 待选道路（候选中除去必有）按规范次序洗牌，洗牌只取决于种子与
172		// 约束内容，因此结果与输入次序、重复及正反写法无关。
173		pool := make([]Edge, 0, len(candidates)-len(reqSet))
174		for _, e := range candidates {
175			if _, ok := reqSet[e]; !ok {
176				pool = append(pool, e)
177			}
178		}
179		rnd := mapRand{state: uint64(seed)}
180		for i := len(pool) - 1; i > 0; i-- {
181			j := int(rnd.next() % uint64(i+1))
182			pool[i], pool[j] = pool[j], pool[i]
183		}
184	
185		// 先沿洗牌次序连通全图，连通后继续按次序补足目标数量。连通阶段
186		// 因端点已属同一分量而跳过的道路记入 skipped：它们仍是合法道路，
187		// 目标数量接近可用道路总数时需要靠它们补足，不能像洗牌耗尽一样
188		// 误判为无解（种子只决定选哪张合法地图，不决定请求能否成功）。
189		chosen := make([]Edge, 0, roadCount)
190		for e := range reqSet {
191			chosen = append(chosen, e)
192		}
193		skipped := make([]Edge, 0)
194		for _, e := range pool {
195			if len(chosen) == roadCount {
196				break
197			}
198			if components > 1 {
199				if uf.union(index[e.From], index[e.To]) {
200					components--
201					chosen = append(chosen, e)
202				} else {
203					skipped = append(skipped, e)
204				}
205			} else {
206				chosen = append(chosen, e)
207			}
208		}
209		if len(chosen) < roadCount {
210			// 走到这里说明连通全图之前 pool 已耗尽（仅在洗牌次序使关键
211			// 连通边排得靠后、而目标数量又需要几乎全部道路时发生）。补做
212			// 一轮 Kruskal：按洗牌次序加入能合并分量的跳过道路；连通后
213			// 剩余名额按洗牌次序由跳过道路补足。可行性检查已保证这些道路
214			// 足以连通全图，且跳过道路总数足以补足目标数量。
215			extraNeeded := roadCount - len(chosen)
216			for _, e := range skipped {
217				if extraNeeded == 0 {
218					break
219				}
220				if components > 1 {
221					if uf.union(index[e.From], index[e.To]) {
222						components--
223						chosen = append(chosen, e)
224						extraNeeded--
225					}
226				} else {
227					chosen = append(chosen, e)
228					extraNeeded--
229				}
230			}
231		}
232		if len(chosen) != roadCount || components > 1 {
233			// 前面的可行性检查已保证有解时不会走到这里。
234			return nil, nil, ruleErrorf("无法生成 %d 条道路的连通地图", roadCount)
235		}
236		sort.Slice(chosen, func(i, j int) bool {
237			if chosen[i].From != chosen[j].From {
238				return chosen[i].From < chosen[j].From
239			}
240			return chosen[i].To < chosen[j].To
241		})
242		return locs, chosen, nil
243	}
244	
245	// checkMapEdge 校验一条必有或禁用道路的端点：必须引用已有地点，
246	// 且不能连接同一地点。
247	func checkMapEdge(e Edge, locSet map[string]struct{}, what string) error {
248		if _, ok := locSet[e.From]; !ok {
249			return ruleErrorf("%s引用了不存在的地点: %q", what, e.From)
250		}
251		if _, ok := locSet[e.To]; !ok {
252			return ruleErrorf("%s引用了不存在的地点: %q", what, e.To)
253		}
254		if e.From == e.To {
255			return ruleErrorf("%s不能连接同一地点: %q", what, e.From)
256		}
257		return nil
258	}
259	
260	// unionFind 是生成地图时用于连通性判断的并查集。
261	type unionFind struct {
262		parent []int
263	}
264	
265	func newUnionFind(n int) *unionFind {
266		parent := make([]int, n)
267		for i := range parent {
268			parent[i] = i
269		}
270		return &unionFind{parent: parent}
271	}
272	
273	func (u *unionFind) find(x int) int {
274		for u.parent[x] != x {
275			u.parent[x] = u.parent[u.parent[x]]
276			x = u.parent[x]
277		}
278		return x
279	}
280	
281	// union 合并两个元素所在集合，原本不在同一集合时返回 true。
282	func (u *unionFind) union(a, b int) bool {
283		ra, rb := u.find(a), u.find(b)
284		if ra == rb {
285			return false
286		}
287		u.parent[ra] = rb
288		return true
289	}
290	
291	// mapRand 是地图生成使用的确定性伪随机源（splitmix64），只由种子决定，
292	// 不依赖任何全局状态，因此同一种子在任何进程中都得到同一序列。
293	type mapRand struct {
294		state uint64
295	}
296	
297	func (r *mapRand) next() uint64 {
298		r.state += 0x9E3779B97F4A7C15
299		z := r.state
300		z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
301		z = (z ^ (z >> 27)) * 0x94D049BB133111EB
302		return z ^ (z >> 31)
