1	package world
2	
3	import (
4		"errors"
5		"math"
6		"math/big"
7		"reflect"
8		"strings"
9		"testing"
10	)
11	
12	// noLimitRules 是不设携带上限、含两个地点与两种物品的规则。
13	func noLimitRules() Rules {
14		return Rules{
15			Version:   "v1",
16			Locations: []string{"hall", "yard"},
17			Edges:     []Edge{{From: "hall", To: "yard"}},
18			ItemKinds: []string{"gold", "key"},
19		}
20	}
21	
22	func mustRuleError(t *testing.T, err error, substrs ...string) {
23		t.Helper()
24		var re *RuleError
25		if !errors.As(err, &re) {
26			t.Fatalf("应返回 *RuleError，得到 %T: %v", err, err)
27		}
28		for _, s := range substrs {
29			if !strings.Contains(re.Reason, s) {
30				t.Fatalf("错误信息应包含 %q: %v", s, re)
31			}
32		}
33	}
34	
35	// 同一角色同一物品的增减与原始数量合并后判断：1 + MaxInt + MinInt = 0，
36	// 且与条目次序无关。
37	func TestApplyMergesDeltasExactly(t *testing.T) {
38		deltas := [][]ItemChange{
39			{{Character: "hero", Item: "gold", Delta: math.MaxInt}, {Character: "hero", Item: "gold", Delta: math.MinInt}},
40			{{Character: "hero", Item: "gold", Delta: math.MinInt}, {Character: "hero", Item: "gold", Delta: math.MaxInt}},
41		}
42		for _, d := range deltas {
43			w, err := NewWorld(InitialData{
44				Seed:  1,
45				Rules: noLimitRules(),
46				Characters: []Character{
47					{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
48				},
49			})
50			if err != nil {
51				t.Fatalf("NewWorld: %v", err)
52			}
53			st, err := w.Apply(Commit{ItemChanges: d, Time: 1})
54			if err != nil {
55				t.Fatalf("合并后结果为 0 应成功: %v", err)
56			}
57			items := st.Characters[0].Items
58			if len(items) != 1 || items[0].Item != "gold" || items[0].Count != 0 {
59				t.Fatalf("最终数量应为 0 且条目保留，得到 %+v", items)
60			}
61		}
62	}
63	
64	// 中途暂时为负、最终合法时应成功，且次序不影响结果。
65	func TestApplyIntermediateNegativeAllowed(t *testing.T) {
66		deltas := [][]ItemChange{
67			{{Character: "hero", Item: "gold", Delta: -2}, {Character: "hero", Item: "gold", Delta: 5}},
68			{{Character: "hero", Item: "gold", Delta: 5}, {Character: "hero", Item: "gold", Delta: -2}},
69		}
70		for _, d := range deltas {
71			w, err := NewWorld(InitialData{
72				Seed:  1,
73				Rules: noLimitRules(),
74				Characters: []Character{
75					{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
76				},
77			})
78			if err != nil {
79				t.Fatalf("NewWorld: %v", err)
80			}
81			st, err := w.Apply(Commit{ItemChanges: d, Time: 1})
82			if err != nil {
83				t.Fatalf("最终数量 4 应成功: %v", err)
84			}
85			if got := st.Characters[0].Items[0].Count; got != 4 {
86				t.Fatalf("最终数量应为 4，得到 %d", got)
87			}
88		}
89	}
90	
91	// 最终数量超出 int 范围或为负时拒绝，并说明角色与物品。
92	func TestApplyFinalCountOutOfRange(t *testing.T) {
93		cases := []struct {
94			name   string
95			count  int
96			deltas []ItemChange
97		}{
