260	// 升级检查按真实总量判断：来源无上限、总量超过 int 最大值，目标设置
261	// 上限时必须报告上限阻碍，并给出完整十进制真实总量。
262	func TestCheckUpgradeTrueTotalOverflow(t *testing.T) {
263		a, _ := newTestArchive(t)
264		w, err := NewWorld(InitialData{
265			Seed:  1,
266			Rules: noLimitRules(),
267			Characters: []Character{
268				{ID: "hero", Location: "hall", Items: []CharacterItem{
