275			t.Fatalf("NewWorld: %v", err)
276		}
277		info, err := a.Save("slot", w)
278		if err != nil {
279			t.Fatalf("Save: %v", err)
280		}
281	
282		target := noLimitRules()
283		target.Version = "v2"
284		target.CarryLimits = map[string]int{"hero": 10}
285		check, err := a.CheckUpgrade("slot", []string{"v1"}, target)
