399	// 校验和正确但违反携带上限的记录：直接读取报损坏，恢复读取与预览按保存
400	// 次序跳过它，分支、确认恢复、升级与迁移都不能把它复制成新记录。
401	func TestReadRejectsLimitViolatingRecord(t *testing.T) {
402		a, _ := newTestArchive(t)
403		badID, goodID := writeIllegalLimitRecord(t, a, a.Dir(), "slot")
404		versions := []string{"v1"}
405	
406		if _, err := a.Latest("slot", versions); err == nil {
407			t.Fatalf("直接读取违反上限的记录应失败")
408		} else {
409			var ce *CorruptError
410			if !errors.As(err, &ce) {
411				t.Fatalf("应返回 *CorruptError，得到 %T: %v", err, err)
412			}
413		}
414		if _, err := a.Record("slot", badID, versions); err == nil {
415			t.Fatalf("按标识读取违反上限的记录应失败")
416		} else {
417			var ce *CorruptError
418			if !errors.As(err, &ce) {
419				t.Fatalf("应返回 *CorruptError，得到 %T: %v", err, err)
420			}
421		}
422	
423		rec, err := a.RecoverLatest("slot", versions)
424		if err != nil {
425			t.Fatalf("RecoverLatest 应跳过非法记录: %v", err)
426		}
427		if rec.ID != goodID {
428			t.Fatalf("恢复应选中更早的合法记录 %s，得到 %s", goodID, rec.ID)
429		}
430		preview, err := a.PreviewRecovery("slot", versions)
431		if err != nil {
432			t.Fatalf("PreviewRecovery 应跳过非法记录: %v", err)
433		}
434		if preview.Current != badID || preview.Source != goodID {
435			t.Fatalf("预览当前/来源应为 %s/%s，得到 %s/%s", badID, goodID, preview.Current, preview.Source)
436		}
437	
438		// 分支不能把非法来源复制成新记录。
439		if _, err := a.Branch("slot", badID, "dst"); err == nil {
440			t.Fatalf("分支非法记录应被拒绝")
441		} else {
442			var ce *CorruptError
443			if !errors.As(err, &ce) {
444				t.Fatalf("分支非法记录应返回 *CorruptError，得到 %T: %v", err, err)
445			}
446		}
447		if _, err := a.readLatestLocked("dst"); err == nil {
448			t.Fatalf("被拒绝的分支不应创建目标槽")
449		}
450	
451		// 确认恢复不能以非法记录为来源。
452		if _, err := a.ConfirmRecovery("slot", badID, badID, versions); err == nil {
453			t.Fatalf("以非法记录为来源的确认恢复应被拒绝")
454		} else {
455			var ce *CorruptError
456			if !errors.As(err, &ce) {
457				t.Fatalf("确认恢复应返回 *CorruptError，得到 %T: %v", err, err)
458			}
459		}
460	
461		// 升级与迁移也不能承接非法来源。
462		target := noLimitRules()
463		target.Version = "v2"
464		if _, err := a.CheckUpgrade("slot", versions, target); err == nil {
465			t.Fatalf("对非法记录的升级检查应失败")
466		} else {
467			var ce *CorruptError
468			if !errors.As(err, &ce) {
469				t.Fatalf("升级检查应返回 *CorruptError，得到 %T: %v", err, err)
470			}
471		}
472		if _, err := a.Upgrade("slot", versions, target, badID); err == nil {
473			t.Fatalf("对非法记录的升级应失败")
474		}
475		if _, err := a.PreviewMigration("slot", versions, target, nil, nil); err == nil {
476			t.Fatalf("对非法记录的迁移预览应失败")
477		}
478		if _, err := a.Migrate("slot", versions, target, nil, nil, badID); err == nil {
479			t.Fatalf("对非法记录的迁移应失败")
480		}
481	
482		// 全部拒绝后槽当前记录与历史不变。
483		latest, err := a.readLatestLocked("slot")
484		if err != nil {
485			t.Fatalf("readLatestLocked: %v", err)
486		}
487		if latest != badID {
488			t.Fatalf("槽当前记录不应改变，得到 %s", latest)
489		}
490		// 历史列表只列通过完整性检查的记录：校验和正确但世界状态非法的
491		// badID 被略过，只留 goodID；槽指针内嵌历史索引不被改写。
492		history, err := a.History("slot")
493		if err != nil {
494			t.Fatalf("History: %v", err)
495		}
496		if len(history) != 1 || history[0].ID != goodID {
497			t.Fatalf("历史列表应只列完好记录: %+v", history)
498		}
499		p, err := a.readSlotPointerLocked("slot")
500		if err != nil {
501			t.Fatal(err)
502		}
503		if len(p.History) != 2 || p.History[0] != badID || p.History[1] != goodID {
504			t.Fatalf("历史索引不应改变: %v", p.History)
505		}
506	}
